#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> graph(n + 1);
    vector<int> indeg(n + 1, 0);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;                   // a 를 b 보다 먼저
        graph[a].push_back(b);
        indeg[b]++;
    }

    queue<int> q;
    for (int v = 1; v <= n; v++)
        if (indeg[v] == 0) q.push(v);    // 시작점은 여러 개일 수 있어요
    vector<int> order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);
        for (int v : graph[u])
            if (--indeg[v] == 0) q.push(v);
    }

    if ((int)order.size() < n) {
        cout << "사이클이 있어서 순서를 정할 수 없음\n";
    } else {
        for (int i = 0; i < n; i++) cout << order[i] << (i + 1 == n ? '\n' : ' ');
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 6;
    vector<pair<int, int>> edges = {{5, 1}, {5, 3}, {1, 2}, {3, 2}, {2, 4}, {6, 4}};
    vector<vector<int>> graph(n + 1);
    vector<int> indeg(n + 1, 0);
    for (auto [a, b] : edges) {
        graph[a].push_back(b);
        indeg[b]++;
    }

    // greater<int>: 번호가 가장 작은 정점부터 (기본 priority_queue 는 가장 큰 것부터)
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int v = 1; v <= n; v++)
        if (indeg[v] == 0) pq.push(v);
    vector<int> order;
    while (!pq.empty()) {
        int u = pq.top();
        pq.pop();
        order.push_back(u);
        for (int v : graph[u])
            if (--indeg[v] == 0) pq.push(v);
    }
    for (int i = 0; i < n; i++) cout << order[i] << (i + 1 == n ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 5;
    vector<int> cost = {0, 3, 2, 4, 1, 5};       // 각 작업에 걸리는 시간 (1번부터)
    vector<pair<int, int>> edges = {{1, 3}, {2, 3}, {3, 5}, {2, 4}, {4, 5}};
    vector<vector<int>> graph(n + 1);
    vector<int> indeg(n + 1, 0);
    for (auto [a, b] : edges) {
        graph[a].push_back(b);
        indeg[b]++;
    }

    vector<long long> finish(n + 1, 0);          // finish[v]: v 가 끝나는 가장 이른 시각
    queue<int> q;
    for (int v = 1; v <= n; v++)
        if (indeg[v] == 0) {
            finish[v] = cost[v];
            q.push(v);
        }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : graph[u]) {
            finish[v] = max(finish[v], finish[u] + cost[v]);   // 앞선 작업이 모두 끝나야 시작
            if (--indeg[v] == 0) q.push(v);
        }
    }
    for (int v = 1; v <= n; v++) cout << finish[v] << (v == n ? '\n' : ' ');
    cout << "전체 " << *max_element(finish.begin(), finish.end()) << '\n';
    return 0;
}
